<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HEALTH_DATABASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/health.db&#39;</span></span>
